import sys

def main():
    # Read all tokens from standard input at once
    input_data = sys.stdin.buffer.read().split()
    if not input_data:
        return

    N = int(input_data[0])

    # Calculate LOG: largest power of 2 such that (1 << LOG) <= N
    LOG = N.bit_length() - 1
    if LOG < 0:
        LOG = 0

    # We allocate a bit array of size up to the maximum index we might visit
    # The maximum index visited in find_kth is exactly (1 << (LOG + 1)) - 1
    max_idx = (1 << (LOG + 1)) - 1
    bit = [0] * (max_idx + 1)

    # Initialize the base available spots (1 if i <= N, 0 otherwise)
    for i in range(1, N + 1):
        bit[i] = 1

    # Build the Fenwick tree in O(max_idx) time
    for i in range(1, max_idx + 1):
        j = i + (i & -i)
        if j <= max_idx:
            bit[j] += bit[i]

    result = [0] * (N + 1)
    start_step = 1 << LOG

    # Process queries in reverse to find the final landing positions
    for i in range(N, 0, -1):
        k = int(input_data[i])  # k is P_i

        # find_kth: binary lifting on Fenwick tree avoids out-of-bounds checks
        # because the tree size is exactly (1 << (LOG + 1)) - 1
        idx = 0
        step = start_step
        while step > 0:
            nxt = idx + step
            if bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            step >>= 1

        pos = idx + 1
        result[pos] = i

        # update Fenwick tree to mark the position as occupied
        curr = pos
        while curr <= max_idx:
            bit[curr] -= 1
            curr += curr & -curr

    # Output the final array efficiently
    sys.stdout.write(' '.join(map(str, result[1:])) + '\n')

if __name__ == '__main__':
    main()
